mapper.insert:
INSERT INTO cli (
tenant_id, name, description, version, install_script, check_command, env_params,
status, is_public, creator, active, create_time, update_time
) VALUES (
#{tenantId}, #{name}, #{description}, #{version}, #{installScript}, #{checkCommand}, #{envParams},
#{status}, #{isPublic}, #{creator}, #{active}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT * FROM cli WHERE active = 1 AND (is_public = 1 OR creator = #{currentUsername})
AND tenant_id = #{tenantId}
AND name LIKE CONCAT('%', #{name}, '%')
AND status = #{status}
ORDER BY update_time DESC
